<script lang="ts" setup>
/**
 * The launch sequence.
 *
 * A short, orchestrated moment that introduces the product before the chat
 * screen takes over. Everything is built from the brand mark that lives in
 * `src/assets/img` (generated by `design/logo/build-assets.py`):
 *
 *   - a deep "ink" field with two slow aurora blobs and a hairline grid
 *   - two faint orbit rings with a satellite riding each of them
 *   - the prism mark, breathing on a glow, with its light beam pulsing
 *   - the wordmark, an eyebrow and the live gateway state
 *
 * The exit is a two-stage crossfade: the ink field dissolves into the paper
 * colour the app itself uses, and only then does the paper dissolve into the
 * chat screen. Nothing of the app shows through the ink, so there is never a
 * moment where text sits on top of text.
 *
 * The timings below are the whole choreography. Entrance beats are CSS
 * keyframes (delayed, `fill-mode: both`); the exit is driven imperatively
 * through the NativeScript animation API so it can be sequenced precisely.
 */
import { computed, onMounted, onUnmounted, ref } from 'vue';
import { Application, Color } from '@nativescript/core';
import { omniRoute, type ConnectionStatus } from '../services/omniroute';

/** Fires once the splash has finished animating away. */
const emit = defineEmits(['done']);

/* ------------------------------------------------------------------ */
/* Palette                                                             */
/* ------------------------------------------------------------------ */
const INK = '#0B0E17';
const PAPER = '#F2F3F6';

/**
 * How long the splash stays on screen once the native views are up.
 * The entrance beats below take ~1.6s, so the mark gets a moment to breathe
 * before it leaves.
 */
const HOLD_MS = 1800;

/** How long the whole exit takes. */
const EXIT_MS = 560;

/**
 * Safety net: if the native `loaded` event never arrives the splash must
 * still get out of the way.
 */
const MAX_LIFE_MS = 6000;

const rootRef = ref(null);
const inkRef = ref(null);
const heroRef = ref(null);
const copyRef = ref(null);
const paperRef = ref(null);

const status = ref<ConnectionStatus>('connecting');
const modelCount = ref(0);

let holdTimer: ReturnType<typeof setTimeout> | undefined;
let exitTimer: ReturnType<typeof setTimeout> | undefined;
let safetyTimer: ReturnType<typeof setTimeout> | undefined;
let unsubscribe: (() => void) | undefined;

/** "ONE GATEWAY · EVERY MODEL" plus the live model count. */
const eyebrow = computed(() =>
  modelCount.value ? `${modelCount.value} MODELS · ONE GATEWAY` : 'ONE GATEWAY · EVERY MODEL',
);

const statusText = computed(() => {
  switch (status.value) {
    case 'connected':
      return 'gateway live';
    case 'error':
    case 'disconnected':
      return 'gateway unreachable';
    default:
      return 'connecting to gateway…';
  }
});

const statusClass = computed(() => `splash-status-dot--${status.value}`);

onMounted(async () => {
  // If the native view is already up (a fast warm start) the `loaded` event
  // has been and gone, so start the sequence by hand.
  if (rootRef.value?.nativeView?.isLoaded) {
    onStageLoaded();
  }

  unsubscribe = omniRoute.onStatus((next) => {
    status.value = next;
  });

  // Warm the model list while the mark is still on screen, so the chat
  // screen opens with its picker ready to use.
  try {
    const models = await omniRoute.loadModels();
    modelCount.value = models.length;
  } catch (err) {
    // The chat screen surfaces connection problems itself; the splash only
    // needs to know that the gateway is not reachable.
    console.error('Splash could not reach OmniRoute:', err);
  }
});

onUnmounted(() => {
  clearTimeout(holdTimer);
  clearTimeout(exitTimer);
  clearTimeout(safetyTimer);
  unsubscribe?.();
  applyStatusBar(false);
});

/**
 * The native views are up: this is the real "frame zero" of the sequence.
 * The timeline is anchored here rather than in the Vue mount - on a slow
 * device those are seconds apart.
 */
function onStageLoaded() {
  // The activity theme has been swapped by now, so this is the first moment
  // the status bar can be painted to match the splash.
  applyStatusBar(true);
  startEntrance();

  clearTimeout(safetyTimer);
  safetyTimer = setTimeout(leave, MAX_LIFE_MS);
  holdTimer = setTimeout(leave, HOLD_MS);
}

/**
 * The entrance.
 *
 * These beats are driven through the NativeScript animation API rather than
 * CSS keyframes: the CSS `animation-delay` is not reliable on Android (a
 * delayed keyframe animation can be restarted before its delay elapses and
 * therefore never start), and the API lets the whole sequence be timed from
 * one place. The infinite ambience - the drifting aurora, the turning
 * orbits, the breathing glow - stays in CSS, where an endless loop belongs.
 */
function startEntrance() {
  const ink = inkRef.value?.nativeView;
  const hero = heroRef.value?.nativeView;
  const copy = copyRef.value?.nativeView;

  // The field itself.
  ink?.animate({ opacity: 1, duration: 520, curve: 'easeOut' });

  // The mark: out of the glow, into place.
  hero?.animate({
    opacity: 1,
    scale: { x: 1, y: 1 },
    duration: 900,
    delay: 120,
    curve: 'easeOut',
  });

  // The wordmark and the state of the gateway.
  copy?.animate({
    opacity: 1,
    translate: { x: 0, y: 0 },
    duration: 800,
    delay: 700,
    curve: 'easeOut',
  });
}

/**
 * The exit: the mark and the copy dissolve first, then the ink field turns
 * into paper, then the paper itself dissolves into the chat screen.
 */
function leave() {
  if (exitTimer) {
    return;
  }

  const ink = inkRef.value?.nativeView;
  const hero = heroRef.value?.nativeView;
  const copy = copyRef.value?.nativeView;
  const paper = paperRef.value?.nativeView;

  hero?.animate({
    opacity: 0,
    scale: { x: 1.16, y: 1.16 },
    duration: 280,
    curve: 'easeIn',
  });
  copy?.animate({
    opacity: 0,
    translate: { x: 0, y: -16 },
    duration: 260,
    curve: 'easeIn',
  });
  ink?.animate({ opacity: 0, duration: 300, delay: 40, curve: 'easeIn' });
  // The ground lightens from ink to paper while it dissolves, so the app
  // arrives on exactly the colour it uses.
  paper?.animate({
    backgroundColor: new Color(PAPER),
    opacity: 0,
    duration: 300,
    delay: 240,
    curve: 'easeIn',
  });

  exitTimer = setTimeout(() => {
    applyStatusBar(false);
    emit('done');
  }, EXIT_MS);
}

/** Paints the system status bar to match whatever is on screen. */
function applyStatusBar(dark: boolean) {
  try {
    // The page owns the window, so this is the supported way to recolour the
    // status bar on Android.
    const page = rootRef.value?.nativeView?.page;
    if (page) {
      page.androidStatusBarBackground = new Color(dark ? INK : PAPER);
    }

    // Light icons on the dark splash, dark icons on the light app.
    const activity = Application.android?.foregroundActivity;
    if (activity && android.os.Build.VERSION.SDK_INT >= 30) {
      const controller = activity.getWindow().getInsetsController();
      const lightBars = (android.view as any).WindowInsetsController
        .APPEARANCE_LIGHT_STATUS_BARS;
      controller.setSystemBarsAppearance(dark ? 0 : lightBars, lightBars);
    }
  } catch (err) {
    // Not fatal - the splash simply keeps the platform default.
    console.error('Could not restyle the status bar:', err);
  }
}
</script>

<template>
  <GridLayout ref="rootRef" rows="*" class="splash-root" @loaded="onStageLoaded">
    <!-- The paper the app fades in from. Sits under everything. -->
    <Label row="0" col="0" text="" class="splash-paper" />

    <!-- The ink field: grid, aurora, orbits and the mark. -->
    <GridLayout ref="inkRef" row="0" col="0" rows="*, auto" class="splash-ink">
      <GridLayout row="0" col="0" class="splash-stage">
        <Image
          row="0"
          col="0"
          src="~/assets/img/grid.png"
          class="splash-grid"
          stretch="fill"
        />

        <Image
          row="0"
          col="0"
          src="~/assets/img/aurora-a.png"
          class="splash-aurora splash-aurora--a"
        />
        <Image
          row="0"
          col="0"
          src="~/assets/img/aurora-b.png"
          class="splash-aurora splash-aurora--b"
        />

        <!-- Two routes orbiting the gateway. -->
        <GridLayout row="0" col="0" class="splash-orbit splash-orbit--outer">
          <Label row="0" col="0" text="" class="splash-ring" />
          <Label row="0" col="0" text="" class="splash-satellite splash-satellite--a" />
        </GridLayout>
        <GridLayout row="0" col="0" class="splash-orbit splash-orbit--inner">
          <Label row="0" col="0" text="" class="splash-ring splash-ring--inner" />
          <Label row="0" col="0" text="" class="splash-satellite splash-satellite--b" />
        </GridLayout>

        <!-- The mark. -->
        <GridLayout ref="heroRef" row="0" col="0" class="splash-hero">
          <Image row="0" col="0" src="~/assets/img/prism-glow.png" class="splash-glow" />
          <GridLayout row="0" col="0" class="splash-mark-box">
            <Image row="0" col="0" src="~/assets/img/prism.png" class="splash-mark" />
            <Image row="0" col="0" src="~/assets/img/prism-beam.png" class="splash-beam" />
          </GridLayout>
        </GridLayout>
      </GridLayout>

      <!-- The wordmark. -->
      <StackLayout ref="copyRef" row="1" col="0" class="splash-copy">
        <Label row="0" col="0" text="OmniRoute" class="splash-wordmark" />
        <Label row="1" col="0" :text="eyebrow" class="splash-eyebrow" />
        <GridLayout row="2" col="0" columns="auto, auto" class="splash-status">
          <Label col="0" row="0" text="●" class="splash-status-dot" :class="statusClass" />
          <Label col="1" row="0" :text="statusText" class="splash-status-text" />
        </GridLayout>
      </StackLayout>
    </GridLayout>
  </GridLayout>
</template>

